// Cat photos for the easter-egg gallery, discovered at build time from
// app/assets/cats/<folder>/ (generated by `pnpm run cats`). Only URLs are
// collected here: the images themselves load when the gallery renders them.
export type CatId = "coquelicot" | "puff";
export type CatFilter = "all" | CatId;

export interface CatPhoto {
  id: string;
  cats: CatId[];
  full: string;
  thumb: string;
}

const files = import.meta.glob("../assets/cats/*/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
}) as Record<string, string>;

// Folder → cats shown in the photo. "ensemble" photos appear under both tabs.
const FOLDER_CATS: Record<string, CatId[]> = {
  coquelicot: ["coquelicot"],
  puff: ["puff"],
  ensemble: ["coquelicot", "puff"],
};

export const CAT_PHOTOS: CatPhoto[] = Object.keys(files)
  .filter((path) => !path.endsWith(".thumb.webp"))
  .sort()
  .map((path) => {
    const [, folder = "", name = ""] = path.match(/cats\/([^/]+)\/([^/]+)\.webp$/) ?? [];
    return {
      id: `${folder}/${name}`,
      cats: FOLDER_CATS[folder] ?? [],
      full: files[path]!,
      thumb: files[path.replace(/\.webp$/, ".thumb.webp")] ?? files[path]!,
    };
  });
